                .mockResolvedValueOnce(['design/active/F-1-root.md', 'design/active/F-2-imported.md'])
                .mockResolvedValueOnce(['design/active/F-2-imported.md', 'design/releases/v1/F-1-root.md']),
            loadProject: vi.fn()
